package io.dndroll.web;

import static org.junit.jupiter.api.Assertions.*;
import io.dndroll.domain.CharacterSheet;
import java.net.*;
import java.net.http.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.context.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.profiles.active=","BOOTSTRAP_USERNAME=a05_owner","BOOTSTRAP_PASSWORD=integration-owner-password"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@org.springframework.context.annotation.Import(RestabilizationEffectsIT.EntropyConfig.class)
class RestabilizationEffectsIT {
    static class ControlledEntropy implements io.dndroll.domain.Dice.Entropy { volatile int d20=20;public int die(int sides){return sides==20?d20:2;} }
    @org.springframework.boot.test.context.TestConfiguration static class EntropyConfig { @org.springframework.context.annotation.Bean @org.springframework.context.annotation.Primary ControlledEntropy controlledEntropy(){return new ControlledEntropy();} }
    @Autowired ControlledEntropy entropy;
    @BeforeEach void resetEntropy(){entropy.d20=20;}
    @LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired PasswordEncoder passwords;
    final JsonMapper json=JsonMapper.builder().build();final Set<UUID> campaigns=new HashSet<>();final Set<String> users=new HashSet<>();
    @DynamicPropertySource static void database(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->FirstSliceIT.required("TEST_DATABASE_URL"));p.add("spring.datasource.username",()->FirstSliceIT.required("TEST_DATABASE_USERNAME"));p.add("spring.datasource.password",()->FirstSliceIT.required("TEST_DATABASE_PASSWORD"));}
    class Browser {
        final HttpClient client=HttpClient.newBuilder().cookieHandler(new CookieManager()).build();String csrf,username;
        HttpResponse<String> get(String path)throws Exception{return client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+path)).GET().build(),HttpResponse.BodyHandlers.ofString());}
        HttpResponse<String> post(String path,Object body)throws Exception{return raw(path,json.writeValueAsString(body),true);}
        HttpResponse<String> raw(String path,String body,boolean token)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://localhost:"+port+path)).header("Content-Type","application/json");if(token)r.header("X-CSRF-TOKEN",csrf);return client.send(r.POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
        Browser()throws Exception{csrf=tree(get("/api/auth/csrf"),200).get("token").asString();}
        void login(String n)throws Exception{username=n;tree(post("/api/auth/login",Map.of("username",n,"password","integration-owner-password")),200);csrf=tree(get("/api/auth/csrf"),200).get("token").asString();}
        JsonNode read(String path)throws Exception{return tree(get(path),200);}
    }
    Browser dm()throws Exception{var b=new Browser();b.login("a05_owner");return b;}
    UUID campaign(Browser dm)throws Exception{var r=tree(dm.post("/api/campaigns",Map.of("requestId",UUID.randomUUID(),"name","ZZZ Dice test")),201);var c=UUID.fromString(r.get("id").asString());campaigns.add(c);return c;}
    Browser player(UUID c)throws Exception{String n="a05_"+UUID.randomUUID().toString().replace("-","").substring(0,12);users.add(n);jdbc.update("insert into app_user(id,username,password_hash) values (?,?,?)",UUID.randomUUID(),n,passwords.encode("integration-owner-password"));jdbc.update("insert into campaign_member(campaign_id,username,role) values (?,?,'PLAYER')",c,n);var b=new Browser();b.login(n);return b;}
    String base(UUID c){return "/api/campaigns/"+c;}
    JsonNode tree(HttpResponse<String> r,int status){assertEquals(status,r.statusCode(),r.body());return r.body().isEmpty()?null:json.readTree(r.body());}
    JsonNode create(Browser b,UUID c,long v,String name)throws Exception{return tree(b.post(base(c)+"/characters",Map.of("requestId",UUID.randomUUID(),"expectedVersion",v,"sheet",CharacterSheet.empty(name))),200);}
    Map<String,Object> roll(long version,String character,String key,String expression,String visibility){return Map.of("requestId",UUID.randomUUID(),"expectedVersion",version,"characterId",character,"key",key,"expression",expression,"visibility",visibility,"advantage",List.of(),"disadvantage",List.of());}
    @AfterEach void cleanup(){
        for(UUID c:campaigns){if(jdbc.queryForObject("select count(*) from information_schema.tables where table_name='stabilization_state'",Integer.class)>0){jdbc.update("delete from stabilization_receipt where campaign_id=?",c);jdbc.update("delete from stabilization_state where campaign_id=?",c);}if(jdbc.queryForObject("select count(*) from information_schema.tables where table_name='attack_preview' and table_schema=current_schema()",Integer.class)>0)jdbc.update("delete from attack_preview where campaign_id=?",c);if(jdbc.queryForObject("select count(*) from information_schema.tables where table_name='combat_action' and table_schema=current_schema()",Integer.class)>0)jdbc.update("delete from combat_action where campaign_id=?",c);if(jdbc.queryForObject("select count(*) from information_schema.tables where table_name='dice_roll' and table_schema=current_schema()",Integer.class)>0)jdbc.update("delete from dice_roll where campaign_id=?",c);jdbc.update("update token set character_id=null where campaign_id=?",c);jdbc.update("delete from character_command_receipt where campaign_id=?",c);jdbc.update("delete from character_card where campaign_id=?",c);jdbc.update("update campaign set current_scene_id=null where id=?",c);jdbc.update("delete from scene where campaign_id=?",c);jdbc.update("delete from campaign_member where campaign_id=?",c);jdbc.update("delete from campaign where id=?",c);}
        jdbc.update("delete from account_command_receipt where actor='a05_owner'");for(String u:users){jdbc.update("delete from account_command_receipt where actor=?",u);jdbc.update("delete from app_user where username=?",u);}
    }


    record Fixture(UUID c,String target,String helper) {}
    Fixture fixture(Browser dm)throws Exception{
        var c=campaign(dm);var s=CharacterSheet.empty("Target");var b=s.combat();
        var sheet=s.change(s.name(),new CharacterSheet.Combat(12,0,7,b.speed(),1,2,b.acMode(),b.manualAc(),b.source()),s.resources(),s.conditions(),s.overrides());
        String target=tree(dm.post(base(c)+"/characters",Map.of("requestId",UUID.randomUUID(),"expectedVersion",0,"sheet",sheet)),200).get("id").asString();
        String helper=create(dm,c,1,"Helper").get("id").asString();return new Fixture(c,target,helper);
    }
    String root(Fixture f){return base(f.c())+"/characters/"+f.target()+"/stabilization";}
    String card(Fixture f,String id){return base(f.c())+"/characters/"+id;}
    Map<String,Object> attempt(Browser dm,Fixture f)throws Exception{return new LinkedHashMap<>(Map.of("requestId",UUID.randomUUID(),"expectedVersion",dm.read(root(f)).get("version").asLong(),"targetVersion",dm.read(card(f,f.target())).get("version").asLong(),"helperId",f.helper(),"helperVersion",dm.read(card(f,f.helper())).get("version").asLong(),"reviewed",true,"reason","Ordinary living not-stable character, legal Help action/contact and no exceptions"));}
    Map<String,Object> review(Browser dm,Fixture f)throws Exception{var s=dm.read(root(f));return new LinkedHashMap<>(Map.of("expectedVersion",s.get("version").asLong(),"targetVersion",dm.read(card(f,f.target())).get("version").asLong(),"helperId",f.helper(),"helperVersion",dm.read(card(f,f.helper())).get("version").asLong(),"rollId",s.get("latest").get("id").asString(),"reviewed",true));}
    Map<String,Object> apply(Map<String,Object> review,JsonNode plan){var b=new LinkedHashMap<>(review);b.put("requestId",UUID.randomUUID());b.put("planHash",plan.get("hash").asString());b.put("reason","Confirm Stable at0HP, remains Unconscious");return b;}
    JsonNode roll(Browser dm,Fixture f)throws Exception{tree(dm.post(root(f)+"/rolls",attempt(dm,f)),200);return dm.read(root(f));}
    int count(String table,Fixture f){return jdbc.queryForObject("select count(*) from "+table+" where campaign_id=?",Integer.class,f.c());}
    void edit(Browser dm,Fixture f,String id)throws Exception{var card=dm.read(card(f,id));var sheet=(tools.jackson.databind.node.ObjectNode)card.get("sheet").deepCopy();sheet.put("notes","later edit "+UUID.randomUUID());tree(dm.post(card(f,id),Map.of("requestId",UUID.randomUUID(),"expectedVersion",card.get("version").asLong(),"sheet",sheet,"reason","Later play")),200);}
    String rr(Fixture f){return root(f)+"/restabilization";}
    void origin(Browser dm,Fixture f,boolean critical)throws Exception{roll(dm,f);var r=review(dm,f);tree(dm.post(root(f)+"/applications",apply(r,tree(dm.post(root(f)+"/preview",r),200))),200);var state=dm.read(root(f));var body=new LinkedHashMap<String,Object>(Map.of("expectedVersion",state.get("version").asLong(),"targetVersion",dm.read(card(f,f.target())).get("version").asLong(),"attemptId",state.get("latest").get("id").asString(),"amount",3,"critical",critical,"reviewed",true));var p=tree(dm.post(root(f)+"/damage-preview",body),200);body.put("requestId",UUID.randomUUID());body.put("planHash",p.get("hash").asString());body.put("reason","PRIVATE original A18 damage");tree(dm.post(root(f)+"/damages",body),200);}
    Map<String,Object> fresh(Browser dm,Fixture f)throws Exception{return new LinkedHashMap<>(Map.of("requestId",UUID.randomUUID(),"expectedVersion",dm.read(rr(f)).get("version").asLong(),"originVersion",dm.read(root(f)).get("version").asLong(),"targetVersion",dm.read(card(f,f.target())).get("version").asLong(),"helperId",f.helper(),"helperVersion",dm.read(card(f,f.helper())).get("version").asLong(),"reviewed",true,"reason","PRIVATE new lawful Help review"));}
    Map<String,Object> restReview(Browser dm,Fixture f)throws Exception{var b=fresh(dm,f);b.remove("requestId");b.remove("reason");b.put("rollId",dm.read(rr(f)).get("latest").get("id").asString());return b;}
    Map<String,Object> restApply(Map<String,Object> r,JsonNode p){var b=new LinkedHashMap<>(r);b.put("requestId",UUID.randomUUID());b.put("planHash",p.get("hash").asString());b.put("reason","PRIVATE restabilization application");return b;}
    @Test void newCheckAndExplicitApplicationRetainOriginalUnconsciousAndResetCountersOnce()throws Exception{
        var dm=dm();var f=fixture(dm);origin(dm,f,true);edit(dm,f,f.helper());var before=dm.read(card(f,f.target()));var helper=dm.read(card(f,f.helper()));var parent=dm.read(root(f));var body=fresh(dm,f);var rollAck=tree(dm.post(rr(f)+"/rolls",body),200);assertEquals(rollAck,tree(dm.post(rr(f)+"/rolls",body),200));assertEquals(before,dm.read(card(f,f.target())));assertEquals(parent,dm.read(root(f)));assertEquals(2,count("dice_roll",f));
        var r=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",r),200);assertEquals("CANDIDATE",p.get("effect").get("status").asString());assertEquals(p,tree(dm.post(rr(f)+"/preview",r),200));var command=restApply(r,p);var ack=tree(dm.post(rr(f)+"/applications",command),200);assertEquals(2,ack.get("version").asLong());assertEquals(ack,tree(dm.post(rr(f)+"/applications",command),200));var after=dm.read(card(f,f.target()));assertEquals(3,after.get("version").asLong());assertEquals(0,after.get("sheet").get("combat").get("hp").asInt());assertEquals(4,after.get("sheet").get("combat").get("tempHp").asInt());assertEquals(0,after.get("sheet").get("combat").get("deathFailures").asInt());assertEquals(0,after.get("sheet").get("combat").get("deathSuccesses").asInt());assertEquals(before.get("sheet").get("conditions").get(0),after.get("sheet").get("conditions").get(1));assertTrue(after.get("sheet").get("conditions").get(0).get("id").asString().startsWith("a19-stable:"));assertEquals(helper,dm.read(card(f,f.helper())));assertEquals(before.get("sheet").get("resources"),after.get("sheet").get("resources"));assertEquals("RESTABILIZED",dm.read(root(f)).get("latest").get("status").asString());assertEquals("APPLIED",dm.read(rr(f)).get("latest").get("status").asString());assertEquals(2,dm.read(rr(f)+"/history").size());assertEquals(4,dm.read(root(f)+"/history").size());
        edit(dm,f,f.target());var later=dm.read(card(f,f.target()));assertEquals(rollAck,tree(dm.post(rr(f)+"/rolls",body),200));assertEquals(ack,tree(dm.post(rr(f)+"/applications",command),200));assertEquals(later,dm.read(card(f,f.target())));assertEquals(2,count("dice_roll",f));command.put("reason","changed retry");tree(dm.post(rr(f)+"/applications",command),409);
    }
    @Test void failedCheckPersistsAndNewActionInvalidatesOldPlanAndCheck()throws Exception{
        var dm=dm();var f=fixture(dm);origin(dm,f,false);var before=dm.read(card(f,f.target()));entropy.d20=1;tree(dm.post(rr(f)+"/rolls",fresh(dm,f)),200);var old=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",old),200);assertEquals("MANUAL_REQUIRED",p.get("effect").get("status").asString());tree(dm.post(rr(f)+"/applications",restApply(old,p)),409);assertEquals(before,dm.read(card(f,f.target())));entropy.d20=20;tree(dm.post(rr(f)+"/rolls",fresh(dm,f)),200);old.put("expectedVersion",2);tree(dm.post(rr(f)+"/preview",old),409);var next=restReview(dm,f);assertEquals("CANDIDATE",tree(dm.post(rr(f)+"/preview",next),200).get("effect").get("status").asString());assertEquals(3,count("dice_roll",f));
    }
    @Test void currentDmCsrfAndPrivateEvidenceAreRequiredEvenForHistoricalReceipts()throws Exception{
        var dm=dm();var f=fixture(dm);var player=player(f.c());jdbc.update("insert into character_controller(campaign_id,character_id,username) values (?,?,?)",f.c(),UUID.fromString(f.target()),player.username);origin(dm,f,true);var body=fresh(dm,f);tree(new Browser().get(rr(f)),401);tree(player.get(rr(f)),403);tree(player.post(rr(f)+"/rolls",body),403);tree(dm.raw(rr(f)+"/rolls",json.writeValueAsString(body),false),403);tree(dm.post(rr(f)+"/rolls",body),200);var r=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",r),200);var command=restApply(r,p);tree(dm.post(rr(f)+"/applications",command),200);var h=player.read(card(f,f.target())+"/history");assertFalse(h.toString().contains("PRIVATE restabilization application"));assertFalse(h.toString().contains("PRIVATE new lawful Help review"));assertEquals("RESTABILIZATION",h.get(h.size()-1).get("kind").asString());var denied=player.get(rr(f)+"/history");tree(denied,403);assertTrue(denied.headers().firstValue("Cache-Control").orElse("").contains("no-store"));assertTrue(dm.read(rr(f)+"/history").toString().contains("PRIVATE restabilization application"));assertEquals(0,player.read(base(f.c())+"/rolls").get("rolls").size());jdbc.update("update campaign_member set role='PLAYER' where campaign_id=? and username=?",f.c(),dm.username);tree(dm.post(rr(f)+"/applications",command),403);jdbc.update("update campaign_member set role='DM' where campaign_id=? and username=?",f.c(),dm.username);tree(dm.post(rr(f)+"/applications",command),200);
    }
    @Test void strictFieldsRejectTotalsFinalValuesAndCoercion()throws Exception{
        var dm=dm();var f=fixture(dm);origin(dm,f,false);var body=fresh(dm,f);for(String key:List.of("total","boundCheck","origin","hp","annotations","actor")){var bad=new LinkedHashMap<>(body);bad.put(key,20);tree(dm.post(rr(f)+"/rolls",bad),400);}for(String key:body.keySet()){var bad=new LinkedHashMap<>(body);bad.remove(key);tree(dm.post(rr(f)+"/rolls",bad),400);}var bad=new LinkedHashMap<>(body);bad.put("originVersion","3");tree(dm.post(rr(f)+"/rolls",bad),400);tree(dm.raw(rr(f)+"/rolls",json.writeValueAsString(body).replace("\"reviewed\":true","\"reviewed\":true,\"reviewed\":false"),true),400);assertEquals(1,count("dice_roll",f));
    }
    @Test void originalDamageFullCardBothVersionsImportReviewAndHelperIdentityAreBound()throws Exception{
        var dm=dm();var missing=fixture(dm);tree(dm.post(rr(missing)+"/rolls",fresh(dm,missing)),409);for(boolean helper:List.of(false,true)){var f=fixture(dm);origin(dm,f,false);var body=fresh(dm,f);jdbc.update("update character_card set import_review=true where id=?",UUID.fromString(helper?f.helper():f.target()));tree(dm.post(rr(f)+"/rolls",body),409);jdbc.update("update character_card set import_review=false where id=?",UUID.fromString(helper?f.helper():f.target()));tree(dm.post(rr(f)+"/rolls",body),200);var r=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",r),200);var wrong=restApply(r,p);wrong.put("planHash","0".repeat(64));tree(dm.post(rr(f)+"/applications",wrong),409);edit(dm,f,helper?f.helper():f.target());tree(dm.post(rr(f)+"/applications",restApply(r,p)),409);var newer=restReview(dm,f);assertEquals("MANUAL_REQUIRED",tree(dm.post(rr(f)+"/preview",newer),200).get("effect").get("status").asString());}
        var f=fixture(dm);origin(dm,f,false);var other=fixture(dm);var body=fresh(dm,f);body.put("helperId",other.helper());tree(dm.post(rr(f)+"/rolls",body),404);body.put("helperId",f.target());body.put("helperVersion",2);tree(dm.post(rr(f)+"/rolls",body),409);body=fresh(dm,f);body.put("originVersion",2);tree(dm.post(rr(f)+"/rolls",body),409);
    }
    @Test void oldAndGenericDiceAndPreseededRequestCannotSupplyTheNewCheck()throws Exception{
        var dm=dm();var f=fixture(dm);origin(dm,f,false);var body=fresh(dm,f);var child=UUID.nameUUIDFromBytes(("A19_RESTABILIZATION:"+body.get("requestId")).getBytes(java.nio.charset.StandardCharsets.UTF_8));var generic=new LinkedHashMap<>(roll(0,f.helper(),"skill:medicine","","DM"));generic.put("requestId",child);tree(dm.post(base(f.c())+"/rolls",generic),200);tree(dm.post(rr(f)+"/rolls",body),409);assertEquals(0,dm.read(rr(f)).get("version").asLong());assertEquals(2,count("dice_roll",f));tree(dm.post(rr(f)+"/rolls",fresh(dm,f)),200);var r=restReview(dm,f);r.put("rollId",dm.read(root(f)).get("latest").get("id").asString());tree(dm.post(rr(f)+"/preview",r),409);
    }
    @Test void sameAndDifferentKeyConcurrencyHasOneDieAndOneApplication()throws Exception{
        var dm=dm();var pool=Executors.newFixedThreadPool(2);try{for(boolean same:List.of(true,false)){var f=fixture(dm);origin(dm,f,false);var one=fresh(dm,f);var two=new LinkedHashMap<>(one);if(!same)two.put("requestId",UUID.randomUUID());var a=pool.submit(()->dm.post(rr(f)+"/rolls",one));var b=pool.submit(()->dm.post(rr(f)+"/rolls",two));var ar=a.get();var br=b.get();if(same)assertEquals(tree(ar,200),tree(br,200));else assertEquals(Set.of(200,409),Set.of(ar.statusCode(),br.statusCode()));assertEquals(2,count("dice_roll",f));var r=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",r),200);var x=restApply(r,p);var y=same?x:restApply(r,p);var aa=pool.submit(()->dm.post(rr(f)+"/applications",x));var bb=pool.submit(()->dm.post(rr(f)+"/applications",y));ar=aa.get();br=bb.get();if(same)assertEquals(tree(ar,200),tree(br,200));else assertEquals(Set.of(200,409),Set.of(ar.statusCode(),br.statusCode()));assertEquals(3,dm.read(card(f,f.target())).get("version").asLong());assertEquals(2,dm.read(rr(f)+"/history").size());}}finally{pool.shutdownNow();}
    }
    @Test void immediateRollAndDeferredApplyFailuresRollbackDieTargetBothLedgersAndReceipts()throws Exception{
        var dm=dm();var f=fixture(dm);origin(dm,f,true);var before=dm.read(card(f,f.target()));var source=dm.read(root(f));var body=fresh(dm,f);jdbc.execute("create function a19_fail() returns trigger language plpgsql as $$ begin raise exception 'injected A19'; return new; end $$");try{jdbc.execute("create trigger a19_failure before insert or update on restabilization_state for each row execute function a19_fail()");assertTrue(dm.post(rr(f)+"/rolls",body).statusCode()>=500);assertEquals(1,count("dice_roll",f));assertEquals(0,count("restabilization_history",f));assertEquals(3,count("stabilization_receipt",f));jdbc.execute("drop trigger a19_failure on restabilization_state");tree(dm.post(rr(f)+"/rolls",body),200);var r=restReview(dm,f);var p=tree(dm.post(rr(f)+"/preview",r),200);var command=restApply(r,p);jdbc.execute("create constraint trigger a19_failure after insert or update on restabilization_state deferrable initially deferred for each row execute function a19_fail()");assertTrue(dm.post(rr(f)+"/applications",command).statusCode()>=500);assertEquals(before,dm.read(card(f,f.target())));assertEquals(source,dm.read(root(f)));assertEquals(1,dm.read(rr(f)).get("version").asLong());assertEquals(1,count("restabilization_history",f));assertEquals(3,count("stabilization_history",f));assertEquals(4,count("stabilization_receipt",f));assertEquals(2,count("dice_roll",f));jdbc.execute("drop trigger a19_failure on restabilization_state");tree(dm.post(rr(f)+"/applications",command),200);}finally{jdbc.execute("drop trigger if exists a19_failure on restabilization_state");jdbc.execute("drop function a19_fail()");}
    }
}
